	f32 least = step;
	bool done = true;

	for (s32 i = 0; i < cmd->count; i++)
	{
		_zanim_object_motion_script* entry = reinterpret_cast<_zanim_object_motion_script*>(reinterpret_cast<char*>(cmd) + 8) + i;
		*dt = step;

		if (!zAnimObjectMotionScriptTick(&entry->header, dt))
			done = false;

		if (*dt < least)
			least = *dt;
	}

	*dt = least;
	return done;
